export const getSongSuggestionsControllerPageV1Url = (
  weddingId: string,
  params?: SongSuggestionsControllerPageV1Params,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/v1/weddings/${weddingId}/song-suggestions?${stringifiedParams}`
    : `/v1/weddings/${weddingId}/song-suggestions`;
};

